def words_in_sentence(sentence):
    """
    Returns a string containing only those words from an original sentence whose lengths are prime numbers.

    :param sentence: A string representing a sentence with space-separated words.
    :return: String of the same order as in input, but including only primes word length's words.
    """

    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    # Join the list of primes length's words into a string with spaces between them, preserving order from original input:
    return ' '.join(prime_length_words)

# Example usage:
